from collections import Counter
from functools import lru_cache

PRICES = {1: 800, 2: 1520, 3: 2160, 4: 2560, 5: 3000}

def naive_greedy(basket):
    counts = sorted(Counter(basket).values(), reverse=True)
    while len(counts) < 5:
        counts.append(0)
    total = 0
    while counts[0] > 0:
        for size in range(5, 0, -1):
            if counts[size - 1] > 0:
                total += PRICES[size]
                for i in range(size):
                    counts[i] -= 1
                counts = sorted(counts, reverse=True)
                break
    return total

def dp_total(basket):
    counts = sorted(Counter(basket).values(), reverse=True)
    while len(counts) < 5:
        counts.append(0)

    @lru_cache(maxsize=None)
    def solve(c):
        if c[0] == 0:
            return 0
        best = 800 * sum(c)  # no-discount upper bound (cents)
        for size in range(1, 6):
            if c[size - 1] > 0:
                nc = list(c)
                for i in range(size):
                    nc[i] -= 1
                nc = tuple(sorted(nc, reverse=True))
                best = min(best, PRICES[size] + solve(nc))
        return best

    return solve(tuple(counts))

cases = {
    "single": ([1], 800),
    "two_same": ([2, 2], 1600),
    "empty": ([], 0),
    "two_diff": ([1, 2], 1520),
